#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/util.h>
#include <string.h>

#ifdef CONFIG_WM8960_EMUL_LOG_LEVEL
#define LOG_LEVEL CONFIG_WM8960_EMUL_LOG_LEVEL
#else
#define LOG_LEVEL CONFIG_EMUL_LOG_LEVEL
#endif

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(wm8960_emul);

#define DT_DRV_COMPAT cirrus_wm8960_emul

#define WM8960_REG_SW_RESET     0x00
#define WM8960_REG_POWER_MGMT_1 0x01
#define WM8960_REG_MAX          0x6F

struct wm8960_emul_data {
    struct i2c_emul_api api;
    uint16_t regs[WM8960_REG_MAX + 1];
};

static int wm8960_emul_read(const struct i2c_emul *emul, int reg, uint16_t *val)
{
    struct wm8960_emul_data *data = (struct wm8960_emul_data *)emul->data;

    if (reg > WM8960_REG_MAX) {
        LOG_ERR("Invalid register address 0x%x", reg);
        return -EINVAL;
    }

    *val = data->regs[reg];
    LOG_DBG("Read reg 0x%x: 0x%x", reg, *val);
    return 0;
}

static int wm8960_emul_write(const struct i2c_emul *emul, int reg, uint16_t val)
{
    struct wm8960_emul_data *data = (struct wm8960_emul_data *)emul->data;

    if (reg > WM8960_REG_MAX) {
        LOG_ERR("Invalid register address 0x%x", reg);
        return -EINVAL;
    }

    LOG_DBG("Write reg 0x%x: 0x%x", reg, val);
    data->regs[reg] = val;

    if (reg == WM8960_REG_SW_RESET && val == 0x0000) {
        LOG_DBG("WM8960 emulator software reset");
        memset(data->regs, 0, sizeof(data->regs));
    }

    return 0;
}

static int wm8960_emul_init(const struct emul *emul, const struct device *parent)
{
    struct wm8960_emul_data *data = (struct wm8960_emul_data *)emul->data;

    LOG_DBG("WM8960 emulator initialized");
    memset(data->regs, 0, sizeof(data->regs));

    return 0;
}

static const struct i2c_emul_api wm8960_emul_api = {
    .read_word = wm8960_emul_read,
    .write_word = wm8960_emul_write,
};

#define WM8960_EMUL_DEFINE(node_id)                                            \
    static struct wm8960_emul_data wm8960_emul_data_##node_id;                 \
    EMUL_DT_INST_DEFINE(node_id, wm8960_emul_init, &wm8960_emul_data_##node_id, \
                        &wm8960_emul_api, NULL)

DT_INST_FOREACH_STATUS_OKAY(WM8960_EMUL_DEFINE)
